import{_ as a,o,c as i,a2 as r}from"./chunks/framework.DpXDHk3d.js";const c=JSON.parse('{"title":"12.1 电气火灾的原因与预防","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/12-chapter-12-dian-qi-fang-huo-fang-bao-yu-chu-dian-ji-jiu/12-1-dian-qi-huo-zai-de-yuan-yin-yu-yu-fang.md","filePath":"electrician/low-voltage-electrician/12-chapter-12-dian-qi-fang-huo-fang-bao-yu-chu-dian-ji-jiu/12-1-dian-qi-huo-zai-de-yuan-yin-yu-yu-fang.md","lastUpdated":1793096070000}'),l={name:"electrician/low-voltage-electrician/12-chapter-12-dian-qi-fang-huo-fang-bao-yu-chu-dian-ji-jiu/12-1-dian-qi-huo-zai-de-yuan-yin-yu-yu-fang.md"};function n(e,t,s,d,u,g){return o(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="_12-1-电气火灾的原因与预防" tabindex="-1">12.1 电气火灾的原因与预防 <a class="header-anchor" href="#_12-1-电气火灾的原因与预防" aria-label="Permalink to &quot;12.1 电气火灾的原因与预防&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>电不会&quot;自燃&quot;,但电流发热、打火能点燃东西。这一节掌握电气火灾的<strong>四大主因</strong>(短路、过载、接触不良、电火花)和预防要点。电气火灾是安全考核的重头戏。</p><h2 id="一、电气火灾的主要原因-必背" tabindex="-1">一、电气火灾的主要原因(必背) <a class="header-anchor" href="#一、电气火灾的主要原因-必背" aria-label="Permalink to &quot;一、电气火灾的主要原因(必背)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>原因</th><th>怎么引发火灾</th></tr></thead><tbody><tr><td><strong>短路</strong></td><td>火线与零线(或两相)相碰,电流骤增,瞬间高温烧燃绝缘和可燃物</td></tr><tr><td><strong>过载</strong></td><td>电流长期超过导线/设备额定值,导线发热,绝缘老化起火</td></tr><tr><td><strong>接触不良</strong></td><td>接头松动、氧化,接触电阻变大,局部高温打火</td></tr><tr><td><strong>电火花、电弧</strong></td><td>开关分断、线路故障产生的火花电弧,点燃可燃气体/粉尘</td></tr><tr><td><strong>静电</strong></td><td>摩擦静电积累放电,引燃易燃易爆物质</td></tr><tr><td><strong>雷击</strong></td><td>雷电流过压、发热引发火灾</td></tr></tbody></table><blockquote><p>💡 通俗理解:<strong>短路是&quot;瞬时大火&quot;,过载是&quot;慢性发烧&quot;,接触不良是&quot;局部暗火&quot;</strong>——三种都靠&quot;发热&quot;点燃可燃物。</p></blockquote><h2 id="二、防止电气火灾的预防措施" tabindex="-1">二、防止电气火灾的预防措施 <a class="header-anchor" href="#二、防止电气火灾的预防措施" aria-label="Permalink to &quot;二、防止电气火灾的预防措施&quot;">​</a></h2><ol><li><strong>正确选择导线、开关、设备</strong>:按负载选截面和额定值,留有余量;</li><li><strong>装设短路保护</strong>(熔断器/断路器)和<strong>过载保护</strong>(热继电器/断路器);</li><li><strong>接头压接牢靠</strong>,定期检查紧固,防松动氧化;</li><li>导线<strong>不随意乱拉乱接</strong>,不私接临时线;</li><li><strong>易燃易爆场所</strong>:用防爆电器,线路按规定敷设,控制电火花;</li><li><strong>静电防护</strong>:易产生静电的设备、管道可靠接地;</li><li>电气设备远离可燃物,留出安全距离。</li></ol><blockquote><p>⚠️ 判断题常考:<strong>导线选细了、开关选大了、接头松动</strong>都容易引发火灾;保护装置(熔断器/断路器)不能随意加大规格。</p></blockquote><h2 id="三、易燃易爆场所的电气要求" tabindex="-1">三、易燃易爆场所的电气要求 <a class="header-anchor" href="#三、易燃易爆场所的电气要求" aria-label="Permalink to &quot;三、易燃易爆场所的电气要求&quot;">​</a></h2><ul><li>使用<strong>防爆型</strong>电气设备(防爆灯具、防爆电机、防爆开关);</li><li>采用<strong>钢管配线</strong>等可靠敷设方式;</li><li>禁止使用普通开关、普通插座,防止电火花;</li><li>通风良好,及时排除易燃易爆气体。</li></ul><blockquote><p>💡 记忆:<strong>&quot;防爆场所,电器要防爆,线路要管护,通风要良好&quot;</strong>。</p></blockquote><h2 id="四、发现电气火灾怎么办-先断电" tabindex="-1">四、发现电气火灾怎么办(先断电) <a class="header-anchor" href="#四、发现电气火灾怎么办-先断电" aria-label="Permalink to &quot;四、发现电气火灾怎么办(先断电)&quot;">​</a></h2><ul><li><strong>先切断电源</strong>再灭火(见 12.2 节);</li><li>无法断电时,用不导电的灭火器材(干粉、二氧化碳)灭火;</li><li>同时报警、疏散人员。</li></ul><h2 id="五、考点提示" tabindex="-1">五、考点提示 <a class="header-anchor" href="#五、考点提示" aria-label="Permalink to &quot;五、考点提示&quot;">​</a></h2><ul><li>✅ 电气火灾四主因:<strong>短路、过载、接触不良、电火花(电弧)</strong>。</li><li>✅ 预防靠:<strong>正确选材、装保护、接头牢、不私接、远离可燃物</strong>。</li><li>✅ 易燃易爆场所用<strong>防爆电器</strong>。</li><li>⚠️ 易混点:短路(瞬时大电流)vs 过载(持续超额定)——都是发热,但过程不同。</li></ul><h2 id="六、本节小结" tabindex="-1">六、本节小结 <a class="header-anchor" href="#六、本节小结" aria-label="Permalink to &quot;六、本节小结&quot;">​</a></h2><ul><li>电气火灾主因:短路、过载、接触不良、电火花,本质都是&quot;发热引燃&quot;。</li><li>预防从选材、保护、接头、管理四方面入手。</li><li>防爆场所必须用防爆电器。</li></ul><h2 id="七、自测练习" tabindex="-1">七、自测练习 <a class="header-anchor" href="#七、自测练习" aria-label="Permalink to &quot;七、自测练习&quot;">​</a></h2><ol><li>(单选)电气火灾最常见的原因之一是()。 A. 短路　B. 电压偏低　C. 频率偏差　D. 电流太小</li><li>(判断)导线长期过载运行,会因发热使绝缘老化,引发火灾。( )</li><li>(单选)易燃易爆场所应使用()电气设备。 A. 普通型　B. 防爆型　C. 加大功率型　D. 户外型</li><li>(判断)导线接头接触不良,接触电阻增大,会产生局部高温。( )</li><li>(判断)发现电气火灾,应首先设法切断电源。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>A</strong>。短路是电气火灾最常见原因之一。</li><li><strong>√</strong>。过载发热使绝缘老化起火。</li><li><strong>B</strong>。易燃易爆场所必须用防爆电器。</li><li><strong>√</strong>。接触不良电阻大、局部高温。</li><li><strong>√</strong>。先断电再灭火。</li></ol></details>',21)])])}const q=a(l,[["render",n]]);export{c as __pageData,q as default};
